'use client';
// "BlackFriday" page, converted from the Claude Design export (Black Friday 2026).
import React from 'react';
import { DCLogic, makeHref } from './runtime';
import HubSpotForm from '@/components/HubSpotForm';

class Logic extends DCLogic {
  END = new Date('2026-11-30T23:59:59-05:00').getTime();
  state = { now: 0, feat: 0, featHover: false, faq: 0, trade: 0, techs: '', tradePick: '', err: '', submitted: false, printN: 0, printing: true, w: 1240 };

  componentDidMount() {
    // The page is pre-rendered: the clock and width start on the client.
    this.setState({ now: Date.now(), w: window.innerWidth });
    this.timer = setInterval(() => this.setState({ now: Date.now() }), 1000);
    this.startFeat();
    this.onResize = () => this.setState({ w: window.innerWidth });
    window.addEventListener('resize', this.onResize);
    this.pt = setTimeout(() => this.setState({ printing: false }), 4000);
    this.motion();
    setTimeout(() => this.reveal(), 80);
  }
  componentDidUpdate() { this.motion(); }
  componentWillUnmount() { clearInterval(this.timer); clearInterval(this.ft); clearTimeout(this.pt); window.removeEventListener('resize', this.onResize); this.io && this.io.disconnect(); }
  motion() { document.documentElement.classList.toggle('zt-nomotion', this.props.motion === false); }

  reveal() {
    if (this.props.motion === false) return;
    this.io = new IntersectionObserver(es => es.forEach(e => {
      if (e.isIntersecting) { e.target.style.opacity = '1'; e.target.style.transform = 'none'; this.io.unobserve(e.target); }
    }), { threshold: 0.1 });
    document.querySelectorAll('[data-reveal]').forEach(el => {
      if (el.getBoundingClientRect().top < window.innerHeight * 0.9) return;
      el.style.opacity = '0'; el.style.transform = 'translateY(28px)';
      el.style.transition = 'opacity .8s cubic-bezier(.2,.7,.2,1), transform .8s cubic-bezier(.2,.7,.2,1)';
      this.io.observe(el);
    });
  }

  scrollTo(id, e) {
    if (e && e.preventDefault) e.preventDefault();
    const el = document.getElementById(id); if (!el) return;
    let p = el.parentElement;
    while (p && p !== document.body && p !== document.documentElement) {
      const s = getComputedStyle(p).overflowY;
      if ((s === 'auto' || s === 'scroll') && p.scrollHeight > p.clientHeight) break;
      p = p.parentElement;
    }
    const top = el.getBoundingClientRect().top - 90;
    if (p && p !== document.body && p !== document.documentElement) p.scrollBy({ top, behavior: 'smooth' });
    else window.scrollBy({ top, behavior: 'smooth' });
  }

  startFeat() { clearInterval(this.ft); this.ft = setInterval(() => { if (!this.state.featHover) this.setState(s => ({ feat: (s.feat + 1) % 6 })); }, 5000); }
  reprint = () => {
    if (this.state.printing) return;
    clearTimeout(this.pt);
    this.setState(s => ({ printN: s.printN + 1, printing: true }));
    this.pt = setTimeout(() => this.setState({ printing: false }), 3600);
  };

  submit = e => {
    e.preventDefault();
    if (!this.state.tradePick) return this.setState({ err: 'Pick your trade.' });
    if (!this.state.techs) return this.setState({ err: 'Pick your number of technicians.' });
    this.setState({ submitted: true, err: '' });
  };

  digits(str, k) {
    return React.createElement('span', { style: { display: 'inline-flex' } },
      str.split('').map((ch, i) => React.createElement('span', { key: k + i + ch, style: { display: 'inline-block', animation: 'zt-roll .4s cubic-bezier(.2,.8,.2,1)' } }, ch)));
  }

  featVals() {
    const { feat, featHover } = this.state;
    const names = ['Scheduling & dispatch', 'Estimates & invoicing', 'Payments', 'Inspections & forms', 'Tech mobile app', 'Customers & pricebook'];
    const o = { featName: names[feat], featCount: '0' + (feat + 1) + ' / 06',
      featHoverOn: () => this.setState({ featHover: true }), featHoverOff: () => this.setState({ featHover: false }) };
    for (let i = 0; i < 6; i++) {
      const on = feat === i;
      o['ft' + i] = { on, bg: on ? '#18181B' : 'transparent', bd: on ? 'rgba(169,196,255,.35)' : 'rgba(255,255,255,.08)', num: on ? '#EE5566' : '#77746C', tc: on ? '#F4F1EA' : '#A7A39A',
        prog: on ? (featHover ? 'none' : 'zt-prog 5s linear both') : 'none',
        pick: () => { this.setState({ feat: i }); this.startFeat(); } };
      o['fp' + i] = { op: on ? 1 : 0, tf: on ? 'none' : 'translateY(16px) scale(.98)', pe: on ? 'auto' : 'none' };
    }
    return o;
  }

  renderVals() {
    const { now, faq, trade, w, printing, printN, techs, tradePick } = this.state;
    const narrow = w < 860;
    const ended = this.props.forceEnded === true || (now > 0 && now >= this.END);
    const diff = now ? Math.max(0, this.END - now) : 0;
    const D = Math.floor(diff / 864e5), H = Math.floor(diff / 36e5) % 24, Mi = Math.floor(diff / 6e4) % 60, S = Math.floor(diff / 1e3) % 60;
    const p = n => (now ? String(n).padStart(2, '0') : '--');
    const tp = [0, 1, 2, 3].map(i => {
      const on = trade === i;
      return { flex: narrow ? 'none' : (on ? '3.2 1 0' : '1 1 0'), h: narrow ? (on ? '400px' : '76px') : '100%', onOp: on ? 1 : 0, offOp: on ? 0 : 1, pe: on ? 'auto' : 'none' };
    });
    const FAQ = [
      ['Who can claim this offer?', 'New ZenTrades customers who sign a 12-month plan between November 13 and November 30, 2026.'],
      ['What exactly do I get?', 'Sign up for 12 months, and you get 3 extra months added on, for 15 months total.'],
      ['How much does ZenTrades cost?', 'Pricing depends on your team and the licenses you need. Fill out the form or book a demo for a quote.'],
      ["What if I'm switching from another software?", "Our onboarding team helps you move your customers and pricebook over so you're not starting from scratch."],
      ['Does ZenTrades work for my trade?', 'ZenTrades is built for HVAC, plumbing, electrical, and fire protection contractors in the US and Canada.'],
      ['What happens after Cyber Monday?', 'The deal ends on November 30. Sign-ups after that are at regular terms.']
    ];
    return {
      wide: !narrow, live: !ended, ended, tapeLoop: [1, 2, 3, 4, 5, 6, 7, 8],
      cd: [[p(D), 'Days'], [p(H), 'Hrs'], [p(Mi), 'Min'], [p(S), 'Sec']].map(([v, l]) => ({ el: this.digits(v, l), l })),
      cdShort: now ? `${D}d ${p(H)}h ${p(Mi)}m ${p(S)}s` : 'Nov 30',
      ztLetters: 'ZenTrades'.split('').map((ch, i) => ({ ch, d: (1.6 + i * 0.07).toFixed(2) + 's' })),
      bfLetters: 'Black Friday'.split('').map((ch, i) => ({ ch, d: (1.2 + i * 0.06).toFixed(2) + 's' })),
      printing, printStatus: printing ? 'Printing…' : 'Tap to reprint', ledColor: printing ? '#EE5566' : '#A9C4FF',
      printAnim: (printN % 2 ? 'zt-printing-b' : 'zt-printing') + ' 3.4s ' + (printN ? '.1s' : '.6s') + ' ease-out both',
      buzzAnim: printing ? 'zt-buzz .1s linear infinite' : 'none', reprint: this.reprint,
      featCols: narrow ? '1fr' : 'repeat(3,minmax(0,1fr))', spanBig: narrow ? 'auto' : 'span 2',
      checks: [{ t: 'Sprinkler heads', delay: '0s' }, { t: 'Fire extinguishers', delay: '.7s' }, { t: 'Alarm panel', delay: '1.4s' }, { t: 'Backflow test', delay: '2.1s' }],
      ...this.featVals(),
      tradeDir: narrow ? 'column' : 'row', tradeH: narrow ? 'auto' : '440px',
      colDir: narrow ? 'row' : 'column', wmode: narrow ? 'horizontal-tb' : 'vertical-rl', wrot: narrow ? 'none' : 'rotate(180deg)',
      tp0: tp[0], tp1: tp[1], tp2: tp[2], tp3: tp[3],
      t0: () => this.setState({ trade: 0 }), t1: () => this.setState({ trade: 1 }), t2: () => this.setState({ trade: 2 }), t3: () => this.setState({ trade: 3 }),
      quotes: [
        { q: "Our dispatcher used to live on the phone. Now she drags a job onto a tech's row and he has it before she hangs up.", name: 'Marcus T.', role: 'Owner, Ridgeline Heating & Air', trade: 'HVAC', ini: 'MT', bg: '#0E0E10', fg: '#F4F1EA', av: '#EE5566', line: 'rgba(255,255,255,.14)' },
        { q: 'Invoices go out from the driveway now. We stopped chasing checks within a week.', name: 'Priya S.', role: 'Office Manager, ClearFlow Plumbing', trade: 'Plumbing', ini: 'PS', bg: '#F4F1EA', fg: '#0E0E10', av: '#A9C4FF', line: '#DDD8CC' },
        { q: 'Inspection reports used to eat my Fridays. Now the forms are done before the tech leaves the building.', name: 'Dan K.', role: 'Ops Lead, Northstar Fire Protection', trade: 'Fire', ini: 'DK', bg: '#EE5566', fg: '#0E0E10', av: '#F4F1EA', line: 'rgba(14,14,16,.2)' },
        { q: 'Switching took a couple of weeks, not months. Onboarding moved our customers and pricebook over for us.', name: 'Jess R.', role: 'Co-owner, Brightline Electric', trade: 'Electrical', ini: 'JR', bg: '#DCE6FF', fg: '#0E0E10', av: '#EE5566', line: 'rgba(14,14,16,.14)' }
      ],
      faqs: FAQ.map(([q, a], i) => ({ q, a, open: faq === i, iconBg: faq === i ? '#EE5566' : '#FFFFFF', iconTf: faq === i ? 'rotate(135deg)' : 'none', toggle: () => this.setState({ faq: faq === i ? -1 : i }) })),
      tradeOpts: ['HVAC', 'Plumbing', 'Electrical', 'Fire protection', 'Other'].map(l => ({ label: l, bg: tradePick === l ? '#0E0E10' : '#FFFFFF', fg: tradePick === l ? '#F4F1EA' : '#0E0E10', bd: tradePick === l ? '#0E0E10' : '#DDD8CC', pick: () => this.setState({ tradePick: l, err: '' }) })),
      techOpts: ['1–5', '6–15', '16–50', '50+'].map(l => ({ label: l, bg: techs === l ? '#0E0E10' : 'transparent', fg: techs === l ? '#F4F1EA' : '#0E0E10', pick: () => this.setState({ techs: l, err: '' }) })),
      formErr: this.state.err, submit: this.submit, submitted: this.state.submitted, notSubmitted: !this.state.submitted,
      bigLetters: ['N', 'O', 'V', '\u00A0', '3', '0'].map((ch, i) => ({ ch, d: (i * 0.12) + 's', w: ch === '\u00A0' ? '.25em' : '0' })),
      goClaim: e => this.scrollTo('claim', e), goHow: e => this.scrollTo('how', e), goFeat: e => this.scrollTo('features', e),
      goTrades: e => this.scrollTo('trades', e), goFaq: e => this.scrollTo('faq', e)
    };
  }
}

